document.documentElement.dataset.workspace='ready';
const toast=document.querySelector('.toast');
let timer;
function notify(text){
  if(!toast)return;
  toast.textContent=text;
  toast.classList.add('show');
  clearTimeout(timer);
  timer=setTimeout(()=>toast.classList.remove('show'),2600);
}
document.querySelectorAll('[data-toast]').forEach(button=>button.addEventListener('click',()=>notify(button.dataset.toast)));
const menu=document.querySelector('.menu'),sidebar=document.querySelector('.sidebar');
menu?.addEventListener('click',()=>{
  sidebar.classList.toggle('open');
  menu.setAttribute('aria-expanded',sidebar.classList.contains('open'));
});
