  providerForm.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(providerForm),name=String(data.get('name')||'').trim(),role=String(data.get('role')),status=String(data.get('status')),policy=String(data.get('policy')||'').trim();if(name.length<2){shell.querySelector('#stage5ProviderFeedback').textContent='نام provider معتبر نیست.';return}const item={id:`provider-${name.toLocaleLowerCase()}`,name,role,status,policy,source:'browser_local',updatedAt:new Date().toISOString()},next=[item,...providers.filter(entry=>entry.id!==item.id)];if(!save(providerKey,next)){shell.querySelector('#stage5ProviderFeedback').textContent='ذخیرهٔ محلی ناموفق بود.';return}providers.splice(0,providers.length,...next);providerForm.reset();shell.querySelector('#stage5ProviderFeedback').textContent='تنظیم provider فقط در مرورگر ذخیره شد؛ انتقال واقعی فعال نیست.';render()});
